INSERT INTO service_process_steps (category_slug, category_name, content) VALUES ('nails', 'Nails', '{\"eyebrow\":\"How It Works\",\"title\":\"Simple, from\",\"titleHighlight\":\"start to finish.\",\"steps\":[{\"n\":\"01\",\"title\":\"Choose Your Service\",\"text\":\"Browse the list below or tell us the occasion — we\'ll suggest what fits.\"},{\"n\":\"02\",\"title\":\"Book a Slot\",\"text\":\"Call, WhatsApp, or fill the form and pick a time that works for you.\"},{\"n\":\"03\",\"title\":\"Meet Your Artist\",\"text\":\"You\'re matched with the specialist best suited to what you need.\"},{\"n\":\"04\",\"title\":\"Leave Glowing\",\"text\":\"Walk out looking — and feeling — exactly the way you wanted to.\"}]}') ON DUPLICATE KEY UPDATE category_name = VALUES(category_name), content = VALUES(content);
